"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0739-01-01:0":{"b": ["Alfonso I (genero di Pelagio) salì al trono (739-757).", "9df77d42"], "d": ["Alfonso I (genero di Pelagio) salì al trono (739-757).", "9df77d42"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0757-05-25:0":{"b": ["I kharigiti sufriti presero Qayrawan", "e215c08e"], "d": ["Dopo il crollo del governatorato omayyade dell'Ifriqiya, Qayrawan fu presa nel 140 (757) da Asim al-Warfajumi, dei kharigiti sufriti.", "a8302c5a"]},
